import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Determine watermark high_ts
    if len(watermark) > 0:
        high_ts = watermark["high_ts"].max()
    else:
        high_ts = None

    # Filter events not yet applied (event_ts > high_ts), or all if no watermark
    if high_ts is not None:
        events = cdc_events[cdc_events["event_ts"] > high_ts].copy()
    else:
        events = cdc_events.copy()

    # Sort events per item in (event_ts, event_seq) order
    events = events.sort_values(by=["item_id", "event_ts", "event_seq"],
                                 kind="mergesort").reset_index(drop=True)

    # Initialize state from target_snapshot
    state = {}
    for _, row in target_snapshot.iterrows():
        item_id = row["item_id"]
        state[item_id] = {
            "qty": float(row["qty_on_hand"]),
            "ts": row["last_event_ts"],
            "exists": True,
        }

    # Apply events sequentially
    for _, ev in events.iterrows():
        item_id = ev["item_id"]
        op = ev["op"]
        qty = ev["qty"]
        event_ts = ev["event_ts"]

        if item_id not in state:
            state[item_id] = {"qty": 0.0, "ts": None, "exists": False}

        s = state[item_id]

        if op == "R":
            if s["exists"]:
                s["qty"] = s["qty"] + qty
            else:
                s["qty"] = 0.0 + qty
                s["exists"] = True
        elif op == "A":
            s["qty"] = qty
            s["exists"] = True
        elif op == "D":
            s["qty"] = 0.0
            s["exists"] = False

        s["ts"] = event_ts

    # Build output: only items that currently exist
    out_rows = []
    for item_id, s in state.items():
        if s["exists"]:
            out_rows.append({
                "item_id": item_id,
                "qty_on_hand": s["qty"],
                "last_event_ts": s["ts"],
            })

    new_snapshot = pd.DataFrame(out_rows, columns=["item_id", "qty_on_hand", "last_event_ts"])

    if len(new_snapshot) > 0:
        new_snapshot["item_id"] = new_snapshot["item_id"].astype("int64")
        new_snapshot["qty_on_hand"] = new_snapshot["qty_on_hand"].astype("float64")
        new_snapshot["last_event_ts"] = pd.to_datetime(new_snapshot["last_event_ts"]).astype("datetime64[us]")
    else:
        new_snapshot = pd.DataFrame({
            "item_id": pd.Series(dtype="int64"),
            "qty_on_hand": pd.Series(dtype="float64"),
            "last_event_ts": pd.Series(dtype="datetime64[us]"),
        })

    return {"new_snapshot": new_snapshot}
